package com.decimalprices;

import lombok.extern.slf4j.Slf4j;
import net.runelite.client.input.KeyManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;

import javax.inject.Inject;

@Slf4j
@PluginDescriptor(name = "Decimal Prices")
public class DecimalPrices extends Plugin {

  @Inject
  private KeyManager keyManager;

  @Inject
  private DecimalPricesKeyListener inputListener;

  @Override
  protected void startUp() {
    keyManager.registerKeyListener(inputListener);
    log.info("Decimal prices started!");
  }

  @Override
  protected void shutDown() {
    keyManager.unregisterKeyListener(inputListener);
    log.info("Decimal prices stopped!");
  }

}

package com.decimalprices;

import lombok.Getter;

import java.math.BigDecimal;
import java.util.HashMap;
import java.util.Map;
import java.util.regex.Pattern;

@Getter
public enum DecimalPricesInputMode {
  MAX_BILLIONS(7, BigDecimal.valueOf(2_147_483_647), Pattern.compile("[0-9]+\\.[0-9]*[kmb]")), MAX_TRILLIONS(30, BigDecimal.valueOf(2_149_631_130_647L), Pattern.compile("[0-9]+\\.[0-9]*[kmbt]"));

  private static final Map<Integer, DecimalPricesInputMode> BY_ID = new HashMap<>();

  static {
    for (DecimalPricesInputMode mode : values()) {
      BY_ID.put(mode.id, mode);
    }
  }

  private final int id;
  private final BigDecimal maxPrice;
  private final Pattern pattern;

  DecimalPricesInputMode(int id, BigDecimal maxPrice, Pattern pattern) {
    this.id = id;
    this.maxPrice = maxPrice;
    this.pattern = pattern;
  }

  public static DecimalPricesInputMode fromId(int id) {
    return BY_ID.get(id);
  }

}

package com.decimalprices;

import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.gameval.VarClientID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.input.KeyListener;

import javax.inject.Inject;
import java.awt.event.KeyEvent;

@Slf4j
class DecimalPricesKeyListener implements KeyListener {

  @Inject
  private Client client;
  @Inject
  private ClientThread clientThread;

  private boolean isTargetInput() {
    final int inputType = client.getVarcIntValue(VarClientID.MESLAYERMODE);
    return DecimalPricesInputMode.fromId(inputType) != null;
  }

  private void convertQuantity() {
    final int inputType = client.getVarcIntValue(VarClientID.MESLAYERMODE);
    final DecimalPricesInputMode inputMode = DecimalPricesInputMode.fromId(inputType);
    if (inputMode == null) {
      return;
    }
    final String rawInputText = client.getVarcStrValue(VarClientID.MESLAYERINPUT);
    if (rawInputText == null || rawInputText.isEmpty()) {
      return;
    }
    // convert to lowercase for validation
    final String lowerInputText = rawInputText.toLowerCase();
    // ensure input matches exactly (any amount of numbers)period(any amount of numbers)[one of only k, m, b or t]
    if (!inputMode.getPattern().matcher(lowerInputText).matches()) {
      return;
    }
    // convert the decimal input to an equivalent integer
    String transformedPrice = DecimalPricesUtil.transformDecimalPrice(lowerInputText, inputMode);
    // set the newly converted integer before it is sent to the server
    clientThread.invoke(() -> client.setVarcStrValue(VarClientID.MESLAYERINPUT, transformedPrice));
  }

  private void addDecimalToInputText() {
    // take current input text and append a period (decimal)
    final String currentInputText = client.getVarcStrValue(VarClientID.MESLAYERINPUT);
    if (currentInputText.isEmpty()) {
      return;
    }
    // prevent adding more than one decimal
    if (currentInputText.contains(".")) {
      return;
    }
    String newInputText = currentInputText + ".";
    clientThread.invoke(() -> client.setVarcStrValue(VarClientID.MESLAYERINPUT, newInputText));
  }

  @Override
  public void keyPressed(KeyEvent e) {
    if (e.getKeyCode() == KeyEvent.VK_ENTER && isTargetInput()) {
      // intercept quantity entry before it is sent to the server
      convertQuantity();
    } else if ((e.getKeyCode() == KeyEvent.VK_PERIOD || e.getKeyCode() == KeyEvent.VK_DECIMAL) && isTargetInput()) {
      // allow typing of decimal in quantity input field which is otherwise not possible to do
      addDecimalToInputText();
    }
  }

  @Override
  public void keyReleased(KeyEvent e) {
  }

  @Override
  public void keyTyped(KeyEvent e) {
  }
}

package com.decimalprices;

import java.math.BigDecimal;

public class DecimalPricesUtil {

  private static final BigDecimal ONE_THOUSAND = BigDecimal.valueOf(1_000);
  private static final BigDecimal ONE_MILLION = BigDecimal.valueOf(1_000_000);
  private static final BigDecimal ONE_BILLION = BigDecimal.valueOf(1_000_000_000);
  private static final BigDecimal ONE_TRILLION = BigDecimal.valueOf(1_000_000_000_000L);

  private DecimalPricesUtil() {
  }

  public static String transformDecimalPrice(String decimalPrice, DecimalPricesInputMode inputMode) {
    int priceStringLen = decimalPrice.length();
    // get the unit from the end of string, k (thousands), m (millions), b (billions) or t (trillions)
    char unit = decimalPrice.charAt(priceStringLen - 1);
    // get the number xx.xx without the unit and parse as a BigDecimal (for precision)
    BigDecimal amount = new BigDecimal(decimalPrice.substring(0, priceStringLen - 1));
    // multiply the number and the unit
    BigDecimal product = calculateProduct(unit, amount);
    // bound result to maximum allowable price
    if (inputMode != null && product.compareTo(inputMode.getMaxPrice()) > 0) {
      product = inputMode.getMaxPrice();
    }
    return product.toBigInteger().toString();
  }

  private static BigDecimal calculateProduct(char unit, BigDecimal amount) {
    BigDecimal product;
    switch (unit) {
      case 'k':
      case 'K':
        product = amount.multiply(ONE_THOUSAND);
        break;
      case 'm':
      case 'M':
        product = amount.multiply(ONE_MILLION);
        break;
      case 'b':
      case 'B':
        product = amount.multiply(ONE_BILLION);
        break;
      case 't':
      case 'T':
        product = amount.multiply(ONE_TRILLION);
        break;
      default:
        product = BigDecimal.ZERO;
        break;
    }
    return product;
  }

}

package com.decimalprices;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class DecimalPricesTest {
  @SuppressWarnings("unchecked")
